local LensGrinder = {}
local PRODUCTS = {
    simple_glass_lens = { name = "Preprosta steklena leča", glassCost = 2, time = 4, cost = 50, science = 22, happiness = 1, description = "Preprosta steklena leča za optiko." },
    polished_reading_lens = { name = "Polirana bralna leča", glassCost = 2, leatherCost = 1, time = 6, cost = 130, science = 35, happiness = 2, prestige = 2, description = "Polirana bralna leča za trgovce." },
    silver_rim_spectacle_lens = { name = "Srebrnookvirna očalna leča", glassCost = 3, silverCost = 1, leatherCost = 1, time = 9, cost = 320, science = 50, happiness = 2, prestige = 6, description = "Srebrnookvirna očalna leča za plemiče." },
    gold_trimmed_telescope_lens = { name = "Zlatookrasni teleskopska leča", glassCost = 4, goldCost = 1, silverCost = 1, leatherCost = 1, time = 13, cost = 760, science = 65, happiness = 3, prestige = 14, description = "Zlatookrasni teleskopska leča za visoke plemiče." },
    jewel_set_microscope_lens = { name = "Draguljasta mikroskopska leča", glassCost = 4, goldCost = 2, silverCost = 1, leatherCost = 1, jewelCost = 1, time = 17, cost = 1700, science = 80, happiness = 5, prestige = 27, description = "Mikroskopska leča z draguljem za visoko plemstvo." },
    royal_grand_lens_set = { name = "Kraljevski veliki set leč", glassCost = 6, goldCost = 3, silverCost = 2, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 3900, science = 95, happiness = 12, prestige = 58, description = "Veliki kraljevski set leč z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    lens_workshop = { name = "Lečna delavnica", cost = { gold = 240, wood = 100, stone = 120, glass = 6 }, upkeep = 5, qualityBonus = 5 },
    optics_loft = { name = "Optična podstrešje", cost = { gold = 880, wood = 240, stone = 240, silver = 6, leather = 6 }, upkeep = 20, qualityBonus = 18 },
    master_optician_atelier = { name = "Mojstrski optični atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_optics_palace = { name = "Kraljevska optična palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
LensGrinder.glassStock = 18; LensGrinder.leatherStock = 10; LensGrinder.silverStock = 6; LensGrinder.goldStock = 6; LensGrinder.jewelStock = 4; LensGrinder.pearlStock = 4
LensGrinder.productStock = {}; LensGrinder.buildings = {}; LensGrinder.maker = nil; LensGrinder.activeMaking = {}; LensGrinder.totalProducts = 0; LensGrinder.dayTimer = 0
function LensGrinder.init() LensGrinder.glassStock=18; LensGrinder.leatherStock=10; LensGrinder.silverStock=6; LensGrinder.goldStock=6; LensGrinder.jewelStock=4; LensGrinder.pearlStock=4; LensGrinder.productStock={}; LensGrinder.buildings={}; LensGrinder.maker=nil; LensGrinder.activeMaking={}; LensGrinder.totalProducts=0; LensGrinder.dayTimer=0; print("[LensGrinder] Royal Lens Grinder System initialized (6 products, 4 buildings)") end
function LensGrinder.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LensGrinder.maker={name=n or ("Lečar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lečar najet: %s (spretnost: %d)",LensGrinder.maker.name,s),"success") end; return true end
function LensGrinder.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LensGrinder.build(id) local ok,e=LensGrinder.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LensGrinder.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LensGrinder.getQualityBonus() local b=0; for _,bd in ipairs(LensGrinder.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LensGrinder.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and LensGrinder.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.leatherCost and LensGrinder.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and LensGrinder.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LensGrinder.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LensGrinder.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LensGrinder.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LensGrinder.buildings==0 then return false,"Potrebna lečna delavnica" end; if not LensGrinder.maker then return false,"Potreben lečar" end; return true end
function LensGrinder.make(pt,qty) qty=qty or 1; local ok,e=LensGrinder.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then LensGrinder.glassStock=LensGrinder.glassStock-d.glassCost*qty end; if d.leatherCost then LensGrinder.leatherStock=LensGrinder.leatherStock-d.leatherCost*qty end; if d.silverCost then LensGrinder.silverStock=LensGrinder.silverStock-d.silverCost*qty end; if d.goldCost then LensGrinder.goldStock=LensGrinder.goldStock-d.goldCost*qty end; if d.jewelCost then LensGrinder.jewelStock=LensGrinder.jewelStock-d.jewelCost*qty end; if d.pearlCost then LensGrinder.pearlStock=LensGrinder.pearlStock-d.pearlCost*qty end; local t=d.time; if LensGrinder.maker then t=math.max(1,t-math.floor(LensGrinder.maker.skill/13)) end; table.insert(LensGrinder.activeMaking,{id="lens_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Poliranje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LensGrinder.completeMaking(m) local q=1.0+(LensGrinder.getQualityBonus()/100); if LensGrinder.maker then q=q+(LensGrinder.maker.skill/150) end; q=math.min(2.4,q); LensGrinder.productStock[m.productType]=(LensGrinder.productStock[m.productType] or 0)+m.quantity; LensGrinder.totalProducts=LensGrinder.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LensGrinder.maker then LensGrinder.maker.itemsMade=LensGrinder.maker.itemsMade+m.quantity; if math.random()<0.25 then LensGrinder.maker.skill=math.min(100,LensGrinder.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Leča izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"lens.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function LensGrinder.update(dt) if not _G.state then return end; LensGrinder.dayTimer=LensGrinder.dayTimer+dt; if LensGrinder.dayTimer>=30 then LensGrinder.dayTimer=0; for i=#LensGrinder.activeMaking,1,-1 do local m=LensGrinder.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LensGrinder.completeMaking(m); table.remove(LensGrinder.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LensGrinder.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LensGrinder.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LensGrinder.getStats() return {glassStock=LensGrinder.glassStock,leatherStock=LensGrinder.leatherStock,silverStock=LensGrinder.silverStock,goldStock=LensGrinder.goldStock,jewelStock=LensGrinder.jewelStock,pearlStock=LensGrinder.pearlStock,productStock=LensGrinder.productStock,numBuildings=#LensGrinder.buildings,hasMaker=LensGrinder.maker~=nil,makerName=LensGrinder.maker and LensGrinder.maker.name or "—",makerSkill=LensGrinder.maker and LensGrinder.maker.skill or 0,activeMaking=#LensGrinder.activeMaking,totalProducts=LensGrinder.totalProducts} end
return LensGrinder
